{
  "aggregate_id": "DEF-NRS-484B-017::electric_bicycle",
  "classifications": [
    {
      "class": "ru.electric_bicycle",
      "verdict": "supported",
      "reason": "The definition expressly admits motor-assisted bicycles through three jurisdictional classes, matching the contract and its jurisdictional class attribute."
    },
    {
      "class": "ru.bicycle",
      "verdict": "underdetermined",
      "reason": "The first alternative can admit human-powered two- or three-wheelers without an assisting motor, defeating complete coverage, while the contract does not establish a qualifying wheel count."
    },
    {
      "class": "ru.moped",
      "verdict": "supported",
      "reason": "The controlling definition expressly states that the term does not include a moped."
    },
    {
      "class": "ru.electric_scooter",
      "verdict": "supported",
      "reason": "The controlling definition expressly states that the term does not include an electric scooter."
    },
    {
      "class": "ru.motorcycle",
      "verdict": "contradicted",
      "reason": "The opening alternative admits the contract's rideable two- or three-wheeled devices independently of the later bicycle-specific qualifications, and neither exception names motorcycles."
    },
    {
      "class": "ru.motor_vehicle",
      "verdict": "supported",
      "reason": "The contract permits both rideable two- or three-wheeled devices reached by the opening alternative and other self-propelled vehicles that the words do not admit."
    },
    {
      "class": "ru.emergency_vehicle",
      "verdict": "supported",
      "reason": "Emergency designation establishes neither the definition's physical characteristics nor an exclusion, and the contract permits devices both within and outside the admitting words."
    },
    {
      "class": "ru.fire_apparatus",
      "verdict": "supported",
      "reason": "The fire-fighting contract fixes neither wheel count nor propulsion characteristics, leaving possible members both within and outside the admitting words."
    },
    {
      "class": "ru.official_vehicle",
      "verdict": "supported",
      "reason": "Official service and identifying equipment do not establish or preclude the physical characteristics specified by the definition."
    },
    {
      "class": "ru.taxicab",
      "verdict": "supported",
      "reason": "The passenger-for-hire contract permits rideable three-wheeled devices as well as vehicles outside the admitting words, without an exception deciding the class."
    },
    {
      "class": "ru.bus",
      "verdict": "underdetermined",
      "reason": "The contract's passenger-carrying purpose establishes neither a disqualifying wheel count nor motor output, so the quoted restrictions do not exclude every member."
    },
    {
      "class": "ru.school_bus",
      "verdict": "underdetermined",
      "reason": "School designation and markings establish no wheel count or motor-output limit that makes the quoted admitting words incompatible with every member."
    },
    {
      "class": "ru.transit_bus",
      "verdict": "underdetermined",
      "reason": "Public transit service and identifying displays do not establish a wheel count or motor output that excludes every member."
    },
    {
      "class": "ru.tour_bus_or_limousine",
      "verdict": "underdetermined",
      "reason": "Neither the bus alternative nor the lengthened passenger-vehicle alternative specifies physical characteristics incompatible with every device admitted by the definition."
    },
    {
      "class": "ru.truck",
      "verdict": "underdetermined",
      "reason": "A goods-carrying body does not establish a disqualifying wheel count or motor output, and the definition contains no truck exception."
    },
    {
      "class": "ru.commercial_motor_vehicle",
      "verdict": "underdetermined",
      "reason": "Commercial licensing alone can satisfy the contract without establishing any wheel count or motor output incompatible with the admitting words."
    },
    {
      "class": "ru.trailer_or_combination",
      "verdict": "underdetermined",
      "reason": "Being drawn or forming a combination does not preclude the opening rideable-device alternative, and the motor-output phrase does not exclude every such member."
    },
    {
      "class": "ru.rail_vehicle",
      "verdict": "underdetermined",
      "reason": "The contract includes other on-track equipment without fixing wheel count, so the quoted words do not establish that no member is admitted."
    },
    {
      "class": "ru.pedestrian",
      "verdict": "supported",
      "reason": "The admitting words describe a rideable device, whereas the contract describes a person rather than that person's conveyance."
    },
    {
      "class": "ru.child",
      "verdict": "supported",
      "reason": "A visibly young pedestrian is a person, not the rideable device described by the admitting words."
    },
    {
      "class": "ru.pedestrian_with_white_cane_or_guide_animal",
      "verdict": "supported",
      "reason": "The contract describes a pedestrian with specified assistance, not a rideable device admitted by the definition."
    }
  ]
}

